&lt;script type=&quot;text/javascript&quot;&gt; Vue.config.productionTip = false //阻止 vue 在启动时生成生产提示。
 const vm = new Vue(&#123; el: &#x27;#root&#x27;, data: &#123; student: &#123; name: &#x27;tom&#x27;, age: 18, hobby: [&#x27;抽烟&#x27;, &#x27;喝酒&#x27;, &#x27;烫头&#x27;], friends: [&#123; name: &#x27;jerry&#x27;, age: 35 &#125;, &#123; name: &#x27;tony&#x27;, age: 36 &#125; ] &#125; &#125;, methods: &#123; addSex() &#123; // Vue.set(this.student,&#x27;sex&#x27;,&#x27;男&#x27;) this.$set(this.student, &#x27;sex&#x27;, &#x27;男&#x27;) &#125;, addFriend() &#123; this.student.friends.unshift(&#123; name: &#x27;jack&#x27;, age: 70 &#125;) &#125;, updateFirstFriendName() &#123; this.student.friends[0].name = &#x27;张三&#x27; &#125;, addHobby() &#123; this.student.hobby.push(&#x27;学习&#x27;) &#125;, updateHobby() &#123; // this.student.hobby.splice(0,1,&#x27;开车&#x27;) // Vue.set(this.student.hobby,0,&#x27;开车&#x27;) this.$set(this.student.hobby, 0, &#x27;开车&#x27;) &#125;, removeSmoke() &#123; this.student.hobby = this.student.hobby.filter((h) =&gt; &#123; return h !== &#x27;抽烟&#x27; &#125;) &#125; &#125; &#125;)&lt;/script&gt;
