&lt;body&gt; &lt;div id=&quot;test&quot;&gt; &lt;input type=&quot;text&quot; v-model=&quot;searchName&quot;&gt; &lt;ul&gt; &lt;li v-for=&quot;(p, index) in filterPersons&quot; :key=&quot;index&quot;&gt; &#123;&#123;index&#125;&#125;—-&#123;&#123;p.name&#125;&#125;—-&#123;&#123;p.age&#125;&#125; &lt;/li&gt; &lt;/ul&gt; &lt;button @click=&quot;setOrderType(1)&quot;&gt;年龄升序&lt;/button&gt; &lt;button @click=&quot;setOrderType(2)&quot;&gt;年龄降序&lt;/button&gt; &lt;button @click=&quot;setOrderType(0)&quot;&gt;还原顺序&lt;/button&gt; &lt;/div&gt;
 &lt;script src=&quot;../js/vue.js&quot;&gt;&lt;/script&gt;
 &lt;script&gt; new Vue(&#123; el: &#x27;#test&#x27;, data: &#123; searchName: &#x27;&#x27;, orderType: 0, //0代表原本， 1代表升序， 2代表降序 persons: [&#123; name: &#x27;Tom&#x27;, age: 10 &#125;, &#123; name: &#x27;Jack&#x27;, age: 16 &#125;, &#123; name: &#x27;Rose&#x27;, age: 12 &#125;, &#123; name: &#x27;Aka&#x27;, age: 18 &#125; ] &#125;, computed: &#123; filterPersons() &#123; // 1. 取出相关数据 const &#123; searchName, persons, orderType &#125; = this; // 解构赋值
 let fPersons;
 // 2. 对persons进行过滤 fPersons = persons.filter(p =&gt; p.name.indexOf(searchName) !== -1);
 // 3. 排序 if (orderType !== 0) &#123; fPersons.sort(function (p1, p2) &#123; // 返回负数p1在前，返回正数p2在前 if (orderType === 2) &#123; return p2.age - p1.age; // 降序 &#125; else &#123; return p1.age - p2.age; // 升序 &#125; &#125;) &#125; return fPersons; &#125; &#125;, methods: &#123; setOrderType(orderType) &#123; this.orderType = orderType; &#125; &#125; &#125;) &lt;/script&gt;&lt;/body&gt;

Vue-基础系列(二)Vue有很多模板语法特别好用，就是在HTML中写一些Vue定义的一些模板语法，可以快速的展现数据，绑定方法等。这也就是Vue上手很快的原因之一。
模板的理解模板就是动态html页面，这里面包含了一些js语法代码
Vue的模板语法分为两种，分别是：

【插值语法】双大括号表达式 （“Mustache”语法）【一个】

【指令语法】指令（以v-开头的自定义标签属性）【很多】


插值语法：
功能：用于解析标签体内容，向页面输出数据

写法：&amp;#123;&amp;#123;xxx&amp;#125;&amp;#125;，xxx是js表达式，且可以直接读取到data中的所有属性，可以调用对象的方法

备注：里面写js表达式：有返回值的js代码，而不是js语句


指令语法：
功能：用于解析标签（包括：标签属性、标签体内容、绑定事件…..）

举例：v-bind:href=&amp;quot;xxx&amp;quot; 或 简写为 :href=&amp;quot;xxx&amp;quot;，xxx同样要写js表达式，且可以直接读取到data中的所有属性

备注：Vue中有很多的指令，且形式都是：v-????


&lt;!DOCTYPE html&gt;&lt;html&gt;    &lt;head&gt;        &lt;meta charset=&quot;UTF-8&quot; /&gt;        &lt;title&gt;模板语法&lt;/title&gt;        &lt;!— 引入Vue —&gt;        &lt;script type=&quot;text/javascript&quot; src=&quot;../js/vue.js&quot;&gt;&lt;/script&gt;    &lt;/head&gt;    &lt;body&gt;
    &amp;lt;!-- 准备好一个容器--&amp;gt;
    &amp;lt;div id=&amp;quot;root&amp;quot;&amp;gt;
        &amp;lt;h1&amp;gt;插值语法&amp;lt;/h1&amp;gt;
        &amp;lt;h3&amp;gt;你好，&amp;#123;&amp;#123;name&amp;#125;&amp;#125;&amp;lt;/h3&amp;gt;
        &amp;lt;hr/&amp;gt;
        &amp;lt;h1&amp;gt;指令语法&amp;lt;/h1&amp;gt;
        &amp;lt;a v-bind:href=&amp;quot;school.url.toUpperCase()&amp;quot; x=&amp;quot;hello&amp;quot;&amp;gt;点我去&amp;#123;&amp;#123;school.name&amp;#125;&amp;#125;学习1&amp;lt;/a&amp;gt;
        &amp;lt;a :href=&amp;quot;school.url&amp;quot; x=&amp;quot;hello&amp;quot;&amp;gt;点我去&amp;#123;&amp;#123;school.name&amp;#125;&amp;#125;学习2&amp;lt;/a&amp;gt;
    &amp;lt;/div&amp;gt;
&amp;lt;/body&amp;gt;

&amp;lt;script type=&amp;quot;text/javascript&amp;quot;&amp;gt;
    Vue.config.productionTip = false //阻止 vue 在启动时生成生产提示。

    new Vue(&amp;#123;
        el:&amp;#x27;#root&amp;#x27;,
        data:&amp;#123;
            name:&amp;#x27;jack&amp;#x27;,
            school:&amp;#123;
                name:&amp;#x27;百度&amp;#x27;,
                url:&amp;#x27;https://www.baidu.com&amp;#x27;,
            &amp;#125;
        &amp;#125;
    &amp;#125;)
&amp;lt;/script&amp;gt;
&lt;/html&gt;
指令语法：强制数据绑定 v-bind:

功能：指定变化的属性值
完整写法
v-bind:xxx=&#x27;yyy&#x27; // yyy会作为表达式解析执行
简洁写法
:xxx=&#x27;yyy&#x27;
单向数据绑定语法：v-bind:href =&amp;quot;xxx&amp;quot; 或简写为 :href =&amp;quot;xxx&amp;quot;
特点：数据只能从 data 流向页面
双向数据绑定 指令 v-model语法：v-mode:value=&amp;quot;xxx&amp;quot; 或简写为 v-model=&amp;quot;xxx&amp;quot;
特点：数据不仅能从 data 流向页面，还能从页面流向 data
指令语法：绑定事件监听 v-on:

功能：绑定指定事件名的回调函数
完整写法
v-on:click=&#x27;xxx&#x27;v-on:keyup=&#x27;xxx(参数)&#x27;v-on:keyup.enter=&#x27;xxx&#x27;
简洁写法
@click=&#x27;xxx&#x27;@keyup=&#x27;xxx&#x27;@keyup.enter=&#x27;xxx&#x27;
v-text与v-html在Vue.js中，v-text和v-html都是用于更新DOM元素内容的指令，但它们的用途和行为有所不同
v-text功能：v-text指令用于将文本内容插入到DOM元素中，并且会覆盖元素中的所有现有内容。与插值语法的区别：v-text会替换掉节点中的内容，&amp;#123;&amp;#123;xx&amp;#125;&amp;#125;则不会。
安全性：v-text会自动对插入的内容进行HTML转义，防止XSS攻击。


示例代码
&lt;!DOCTYPE html&gt;&lt;html&gt;&lt;head&gt; &lt;title&gt;Vue v-text Example&lt;/title&gt; &lt;script src=&quot;https://cdn.jsdelivr.net/npm/vue@2/dist/vue.js&quot;&gt;&lt;/script&amp;gt;&lt;/head&gt;&lt;body&gt; &lt;div id=&quot;app&quot;&gt; &lt;p v-text=&quot;message&quot;&gt;&lt;/p&gt; &lt;/div&gt;
 &lt;script&gt; new Vue(&#123; el: &#x27;#app&#x27;, data: &#123; message: &#x27;&lt;strong&gt;Hello Vue!&lt;/strong&gt;&#x27; &#125; &#125;); &lt;/script&gt;&lt;/body&gt;&lt;/html&gt;


解释：v-text=&amp;quot;message&amp;quot;将message的数据绑定到&amp;lt;p&amp;gt;元素中，并以纯文本形式显示内容，即使message包含HTML标签也会被转义为文本。


渲染结果：
&lt;p&gt;&amp;lt;strong&amp;gt;Hello Vue!&amp;lt;/strong&amp;gt;&lt;/p&gt;
v-html功能：v-html指令用于将HTML内容插入到DOM元素中，并且会覆盖元素中的所有现有内容。
安全性：v-html不会对插入的内容进行HTML转义，因此它会直接渲染HTML标签。这意味着，如果插入的内容来自不受信任的源，可能会引发XSS攻击风险。因此，在使用v-html时要非常小心，确保插入的HTML内容是安全的。


示例代码
&lt;!DOCTYPE html&gt;&lt;html&gt;&lt;head&gt; &lt;title&gt;Vue v-html Example&lt;/title&gt; &lt;script src=&quot;https://cdn.jsdelivr.net/npm/vue@2/dist/vue.js&quot;&gt;&lt;/script&amp;gt;&lt;/head&gt;&lt;body&gt; &lt;div id=&quot;app&quot;&gt; &lt;p v-html=&quot;message&quot;&gt;&lt;/p&gt; &lt;/div&gt;
 &lt;script&gt; new Vue(&#123; el: &#x27;#app&#x27;, data: &#123; message: &#x27;&lt;strong&gt;Hello Vue!&lt;/strong&gt;&#x27; &#125; &#125;); &lt;/script&gt;&lt;/body&gt;&lt;/html&gt;


解释：v-html=&amp;quot;message&amp;quot;将message的数据绑定到&amp;lt;p&amp;gt;元素中，并将其作为HTML内容渲染。HTML标签在内容中会被正常解析并显示为HTML。
&lt;p&gt;&lt;strong&gt;Hello Vue!&lt;/strong&gt;&lt;/p&gt;
区别总结v-text：用于插入纯文本内容，自动进行HTML转义，安全性较高。v-html：用于插入HTML内容，不进行转义，直接渲染HTML标签，需注意潜在的安全风险。


在选择使用v-text或v-html时，考虑到安全性，通常建议尽可能使用v-text，只有在确实需要动态插入和渲染HTML内容时才使用v-html，并确保插入的内容是安全的。
条件渲染指令在Vue.js中，条件渲染指令用于根据表达式的结果动态地控制DOM元素的显示或隐藏。主要的条件渲染指令有 v-if、v-else-if、v-else 和 v-show。
v-if 指令功能：v-if 指令用于根据表达式的布尔值决定是否在DOM中渲染元素。如果表达式为 true，则渲染该元素；否则移除该元素及其子元素。
性能：v-if 是“真正的”条件渲染，因为在条件为 false 时，Vue 不会渲染元素和子元素，因此在性能上比 v-show 更节省资源，尤其是在切换频率较低的场景中。


示例代码
&lt;!DOCTYPE html&gt;&lt;html&gt;&lt;head&gt; &lt;title&gt;Vue v-if Example&lt;/title&gt; &lt;script src=&quot;https://cdn.jsdelivr.net/npm/vue@2/dist/vue.js&quot;&gt;&lt;/script&amp;gt;&lt;/head&gt;&lt;body&gt; &lt;div id=&quot;app&quot;&gt; &lt;p v-if=&quot;isVisible&quot;&gt;This text is conditionally rendered.&lt;/p&gt; &lt;/div&gt;
 &lt;script&gt; new Vue(&#123; el: &#x27;#app&#x27;, data: &#123; isVisible: true &#125; &#125;); &lt;/script&gt;&lt;/body&gt;&lt;/html&gt;


解释：当 isVisible 为 true 时，&amp;lt;p&amp;gt; 元素会被渲染；当 isVisible 为 false 时，该元素会从DOM中移除。
v-else-if 指令功能：v-else-if 是 v-if 的延伸，用于添加多个条件。如果前面的 v-if 或 v-else-if 条件不满足，而当前条件满足时，该元素会被渲染。


示例代码
&lt;!DOCTYPE html&gt;&lt;html&gt;&lt;head&gt; &lt;title&gt;Vue v-else-if Example&lt;/title&gt; &lt;script src=&quot;https://cdn.jsdelivr.net/npm/vue@2/dist/vue.js&quot;&gt;&lt;/script&amp;gt;&lt;/head&gt;&lt;body&gt; &lt;div id=&quot;app&quot;&gt; &lt;p v-if=&quot;type === &#x27;A&#x27;&quot;&gt;Type A&lt;/p&gt; &lt;p v-else-if=&quot;type === &#x27;B&#x27;&quot;&gt;Type B&lt;/p&gt; &lt;p v-else-if=&quot;type === &#x27;C&#x27;&quot;&gt;Type C&lt;/p&gt; &lt;/div&gt;
 &lt;script&gt; new Vue(&#123; el: &#x27;#app&#x27;, data: &#123; type: &#x27;B&#x27; &#125; &#125;); &lt;/script&gt;&lt;/body&gt;&lt;/html&gt;


解释：当 type 为 ‘B’ 时，&amp;lt;p&amp;gt; 元素显示 “Type B”；若 type 为 ‘A’ 或 ‘C’，则显示对应内容。
v-else 指令功能：v-else 指令用于在前面的 v-if 和 v-else-if 条件都不满足时渲染元素。


示例代码
&lt;!DOCTYPE html&gt;&lt;html&gt;&lt;head&gt; &lt;title&gt;Vue v-else Example&lt;/title&gt; &lt;script src=&quot;https://cdn.jsdelivr.net/npm/vue@2/dist/vue.js&quot;&gt;&lt;/script&amp;gt;&lt;/head&gt;&lt;body&gt; &lt;div id=&quot;app&quot;&gt; &lt;p v-if=&quot;type === &#x27;A&#x27;&quot;&gt;Type A&lt;/p&gt; &lt;p v-else-if=&quot;type === &#x27;B&#x27;&quot;&gt;Type B&lt;/p&gt; &lt;p v-else&gt;Type C&lt;/p&gt; &lt;/div&gt;
 &lt;script&gt; new Vue(&#123; el: &#x27;#app&#x27;, data: &#123; type: &#x27;C&#x27; &#125; &#125;); &lt;/script&gt;&lt;/body&gt;&lt;/html&gt;


解释：当 type 既不是 ‘A’ 也不是 ‘B’ 时，&amp;lt;p&amp;gt; 元素显示 “Type C”。
v-show 指令功能：v-show 指令也用于条件渲染，但与 v-if 不同的是，v-show 仅控制元素的 display CSS 属性（显示或隐藏），不会从DOM中移除元素。


示例代码
&lt;!DOCTYPE html&gt;&lt;html&gt;&lt;head&gt; &lt;title&gt;Vue v-show Example&lt;/title&gt; &lt;script src=&quot;https://cdn.jsdelivr.net/npm/vue@2/dist/vue.js&quot;&gt;&lt;/script&amp;gt;&lt;/head&gt;&lt;body&gt; &lt;div id=&quot;app&quot;&gt; &lt;p v-show=&quot;isVisible&quot;&gt;This text is conditionally shown.&lt;/p&gt; &lt;/div&gt;
 &lt;script&gt; new Vue(&#123; el: &#x27;#app&#x27;, data: &#123; isVisible: true &#125; &#125;); &lt;/script&gt;&lt;/body&gt;&lt;/html&gt;


解释：当 isVisible 为 true 时，&amp;lt;p&amp;gt; 元素显示；当 isVisible 为 false 时，&amp;lt;p&amp;gt; 元素隐藏（display: none;），但仍然保留在DOM中。
v-if vs v-showv-if：适合在需要条件切换频率较低的场景中使用，因为它会在条件为 false 时移除元素，节省性能。
v-show：适合在需要频繁切换显示的场景中使用，因为它仅切换 display 属性，不涉及DOM元素的移除和重建，切换速度较快。


使用v-if的时候，元素可能无法获取到，而使用v-show一定可以获取到
总结
v-text : 更新元素的 textContent

v-html : 更新元素的 innerHTML

v-if : 如果为true, 当前标签才会输出到页面

v-else: 如果为false, 当前标签才会输出到页面

v-show : 通过控制display样式来控制显示&#x2F;隐藏

v-for : 遍历数组&#x2F;对象

v-on : 绑定事件监听, 一般简写为@

v-bind : 强制绑定解析表达式, 可以省略v-bind

v-model : 双向数据绑定

ref : 为某个元素注册一个唯一标识, vue对象通过$refs属性访问这个元素对象

v-cloak : 使用它防止闪现表达式, 与css配合: [v-cloak] { display: none }


事件修饰符.stop：阻止事件冒泡。例如，@click.stop会阻止点击事件继续向上冒泡到父元素。
.prevent：阻止默认事件。例如，@submit.prevent会阻止表单的提交行为。
.capture：使用事件捕获模式而不是冒泡模式。默认情况下，事件是在冒泡阶段触发的，使用.capture修饰符可以改变为捕获阶段触发。
.self：只有当事件的目标是当前元素本身时才触发事件处理程序。如果事件冒泡到了目标元素的子元素，事件处理程序将不会被触发。
.once：事件只会触发一次，即使在同一个元素上多次触发该事件。
.passive：指示浏览器不应该阻止事件的默认行为。这对于滚动事件等性能敏感的事件非常有用。

样式绑定在应用界面中, 某个(些)元素的样式是变化的，class&#x2F;style 绑定就是专门用来实现动态样式效果的技术
class 绑定:class=&#x27;xxx&#x27; // xxx可以是字符串、对象、数组。
字符串表达式是字符串: &amp;#39;classA&amp;#39;


适用于：类名不确定，要动态获取
&lt;!DOCTYPE html&gt;&lt;html&gt;
&lt;head&gt; &lt;meta charset=&quot;UTF-8&quot; /&gt; &lt;title&gt;绑定样式&lt;/title&gt; &lt;style&gt; .basic &#123; width: 400px; height: 100px; border: 1px solid black; &#125;
 .happy &#123; border: 4px solid red; ; background-color: rgba(255, 255, 0, 0.644); background: linear-gradient(30deg, yellow, pink, orange, yellow); &#125;
 .sad &#123; border: 4px dashed rgb(2, 197, 2); background-color: gray; &#125;
 .normal &#123; background-color: skyblue; &#125;
 &lt;/style&gt; &lt;script src=&quot;https://cdn.bootcdn.net/ajax/libs/vue/2.6.12/vue.js&quot;&gt;&lt;/script&amp;gt;&lt;/head&gt;
&lt;body&gt;
 &lt;!— 准备好一个容器—&gt; &lt;div id=&quot;root&quot;&gt; &lt;!— 绑定class样式—字符串写法，适用于：样式的类名不确定，需要动态指定 —&gt; &lt;div class=&quot;basic&quot; :class=&quot;mood&quot; @click=&quot;changeMood&quot;&gt;&#123;&#123;name&#125;&#125;&lt;/div&gt; &lt;/div&gt;&lt;/body&gt;
&lt;script type=&quot;text/javascript&quot;&gt; Vue.config.productionTip = false
 const vm = new Vue(&#123; el: &#x27;#root&#x27;, data: &#123; name: &#x27;YK菌&#x27;, mood: &#x27;normal&#x27; &#125;, methods: &#123; changeMood() &#123; const arr = [&#x27;happy&#x27;, &#x27;sad&#x27;, &#x27;normal&#x27;] const index = Math.floor(Math.random() * 3) this.mood = arr[index] &#125; &#125;, &#125;)&lt;/script&gt;
&lt;/html&gt;

对象表达式是对象: &amp;#123;classA:isA, classB: isB&amp;#125;


适用于：要绑定多个样式，个数不确定，名字也不确定
对象语法用于根据条件添加或移除类名。对象的键是类名，值是布尔值，布尔值为 true 时应用该类名，为 false 时移除该类名。
&lt;div v-bind:class=&quot;&#123; active: isActive, &#x27;text-danger&#x27;: hasError &#125;&quot;&gt;&lt;/div&gt;


在上面的例子中，如果 isActive 为 true，active 类将被添加到 div 中。同样，如果 hasError 为 true，text-danger 类将被添加。
&lt;!DOCTYPE html&gt;&lt;html&gt;
&lt;head&gt; &lt;meta charset=&quot;UTF-8&quot; /&gt; &lt;title&gt;绑定样式&lt;/title&gt; &lt;style&gt; .basic &#123; width: 400px; height: 100px; border: 1px solid black; &#125;
 .yk1 &#123; background-color: yellowgreen; &#125;
 .yk2 &#123; font-size: 30px; text-shadow: 2px 2px 10px red; &#125;
 .yk3 &#123; border-radius: 20px; &#125; &lt;/style&gt; &lt;script src=&quot;https://cdn.bootcdn.net/ajax/libs/vue/2.6.12/vue.js&quot;&gt;&lt;/script&amp;gt;&lt;/head&gt;
&lt;body&gt;
 &lt;!— 准备好一个容器—&gt; &lt;div id=&quot;root&quot;&gt; &lt;!— 绑定class样式—数组写法，适用于：要绑定的样式个数不确定、名字也不确定 —&gt; &lt;div class=&quot;basic&quot; :class=&quot;classArr&quot;&gt;&#123;&#123;name&#125;&#125;&lt;/div&gt; &lt;br /&gt;&lt;br /&gt; &lt;/div&gt;&lt;/body&gt;
&lt;script type=&quot;text/javascript&quot;&gt; Vue.config.productionTip = false
 const vm = new Vue(&#123; el: &#x27;#root&#x27;, data: &#123; name: &#x27;YK菌&#x27;, classArr: [&#x27;yk1&#x27;, &#x27;yk2&#x27;, &#x27;yk3&#x27;] &#125;, &#125;)&lt;/script&gt;
&lt;/html&gt;

数组表达式是数组: [&amp;#39;classA&amp;#39;, &amp;#39;classB&amp;#39;]


适用于：要绑定多个样式，个数确定，名字也确定，但不确定用不用
&lt;!DOCTYPE html&gt;&lt;html&gt;
&lt;head&gt; &lt;meta charset=&quot;UTF-8&quot; /&gt; &lt;title&gt;绑定样式&lt;/title&gt; &lt;style&gt; .basic &#123; width: 400px; height: 100px; border: 1px solid black; &#125;
 .yk1 &#123; background-color: yellowgreen; &#125;
 .yk2 &#123; font-size: 30px; text-shadow: 2px 2px 10px red; &#125;
 .yk3 &#123; border-radius: 20px; &#125; &lt;/style&gt; &lt;script src=&quot;https://cdn.bootcdn.net/ajax/libs/vue/2.6.12/vue.js&quot;&gt;&lt;/script&amp;gt;&lt;/head&gt;
&lt;body&gt;
 &lt;!— 准备好一个容器—&gt; &lt;div id=&quot;root&quot;&gt; &lt;!— 绑定class样式—对象写法，适用于：要绑定的样式个数确定、名字也确定，但要动态决定用不用 —&gt; &lt;div class=&quot;basic&quot; :class=&quot;classObj&quot;&gt;&#123;&#123;name&#125;&#125;&lt;/div&gt; &lt;/div&gt;&lt;/body&gt;
&lt;script type=&quot;text/javascript&quot;&gt; Vue.config.productionTip = false
 const vm = new Vue(&#123; el: &#x27;#root&#x27;, data: &#123; name: &#x27;YK菌&#x27;, classObj: &#123; yk1: true, yk2: false, yk3: true &#125; &#125; &#125;)&lt;/script&gt;
&lt;/html&gt;

style 绑定:style=&quot;&#123; color: activeColor, fontSize: fontSize + &#x27;px&#x27; &#125;&quot;


其中 activeColor&#x2F;fontSize 是 data 属性
:style=&quot;&#123;fontSize: xxx&#125;&quot;其中xxx是动态值。:style=&quot;[a,b]&quot;其中a、b是样式对象。
对象&lt;!DOCTYPE html&gt;&lt;html&gt;
&lt;head&gt; &lt;meta charset=&quot;UTF-8&quot; /&gt; &lt;title&gt;绑定样式&lt;/title&gt; &lt;style&gt; .basic &#123; width: 400px; height: 100px; border: 1px solid black; &#125; &lt;/style&gt; &lt;script src=&quot;https://cdn.bootcdn.net/ajax/libs/vue/2.6.12/vue.js&quot;&gt;&lt;/script&amp;gt;&lt;/head&gt;
&lt;body&gt;
 &lt;!— 准备好一个容器—&gt; &lt;div id=&quot;root&quot;&gt;
 &lt;!— 绑定style样式—对象写法 —&gt; &lt;div class=&quot;basic&quot; :style=&quot;styleObj, styleObj2&quot;&gt;&#123;&#123;name&#125;&#125;&lt;/div&gt;
 &lt;/div&gt;&lt;/body&gt;
&lt;script type=&quot;text/javascript&quot;&gt; Vue.config.productionTip = false
