&lt;script type=&quot;text/javascript&quot;&gt; Vue.config.productionTip = false
 new Vue(&#123; el: &#x27;#root&#x27;, data: &#123; userInfo: &#123; account: &#x27;&#x27;, password: &#x27;&#x27;, age: 18, sex: &#x27;female&#x27; &#125; &#125; &#125;)&lt;/script&gt;
